def main():
    import sys
    import math

    def readints():
        return list(map(int, sys.stdin.readline().split()))

    n = int(sys.stdin.readline())
    heights = readints()

    # Calculate the number of maxima hills
    maxima = [True] * n
    for i in range(1, n):
        if heights[i] <= heights[i - 1]:
            maxima[i] = False
    for i in range(n - 2, -1, -1):
        if heights[i] <= heights[i + 1]:
            maxima[i] = False

    # Count the number of maxima
    num_maxima = sum(maxima)

    # If the number of maxima is already greater than or equal to ceil(n/2), no operations are needed
    if num_maxima >= math.ceil(n / 2):
        result = [0] * math.ceil(n / 2)
    else:
        # Calculate the number of operations needed to create more maxima
        operations = []
        for i in range(1, n - 1):
            if not maxima[i]:
                left_height = heights[i - 1]
                right_height = heights[i + 1]
                if left_height > heights[i] and right_height > heights[i]:
                    operations.append((heights[i], i))

        operations.sort()
        result = []
        current_operations = 0
        current_maxima = num_maxima

        for i in range(1, math.ceil(n / 2) + 1):
            while current_maxima < i and operations:
                _, index = operations.pop(0)
                current_operations += 1
                if index > 0 and index < n - 1:
                    if heights[index - 1] > heights[index] and heights[index + 1] > heights[index]:
                        current_maxima += 1
            result.append(current_operations)

    print(" ".join(map(str, result)))

