import sys
from math import ceil

def min_hours_to_build_houses(n, heights):
    dp = [[float('inf')] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(i + 1):
            dp[i][j] = dp[i - 1][j]
            if j > 0 and (i == 1 or heights[i - 1] > heights[i - 2]):
                dp[i][j] = min(dp[i][j], dp[i - 1][j - 1])
            if i > 1:
                dp[i][j] = min(dp[i][j], dp[i - 1][j] + heights[i - 1] - heights[i - 2])

    result = []
    for k in range(1, ceil(n / 2) + 1):
        result.append(dp[n][k])

    return result

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    heights = list(map(int, data[1:]))

    result = min_hours_to_build_houses(n, heights)
    print(" ".join(map(str, result)))

